const T={
amor:["Una conversación pendiente por fin fluye con naturalidad.","Alguien cercano te sorprende con un gesto sincero.","Es buen momento para decir lo que sientes sin rodeos.","Cuida los silencios: hoy valen más que las palabras.","Una vieja amistad se acerca con novedades agradables."],
trabajo:["Un proyecto detenido recupera impulso a mitad de semana.","Escucha más de lo que hablas; ahí está la oportunidad.","Ordena prioridades antes del jueves y todo rendirá más.","Una propuesta inesperada merece que la pienses con calma.","Tu constancia empieza a notarse ante los demás."],
energia:["Tu energía sube hacia el fin de semana; resérvala para lo que amas.","Descansar bien será tu mejor estrategia estos días.","Salir a caminar al atardecer te devolverá claridad.","Evita acumular pendientes: resuélvelos de uno en uno.","Rodéate de gente que te sume y suelta lo que pesa."]
};
const C=["Número de la suerte","Color de la semana"];
const cols=["dorado","azul noche","verde jade","coral","violeta","plata","turquesa"];
const TRAIT={Aries:"Aries, tu fuego natural te empuja a tomar la iniciativa; esta semana conviene canalizarlo con un objetivo claro en lugar de dispersarlo.",Tauro:"Tauro, tu constancia es tu mayor tesoro; esta semana te pide disfrutar lo que ya construiste sin dejar de cuidar tus cimientos.",Géminis:"Géminis, tu curiosidad abre puertas que otros no ven; esta semana tus palabras y tu ingenio tendrán un peso especial.",Cáncer:"Cáncer, tu sensibilidad es una brújula confiable; esta semana te invita a proteger tu espacio y a rodearte de quienes te hacen sentir en casa.",Leo:"Leo, tu luz propia llama la atención sin esfuerzo; esta semana brillas más cuando compartes el escenario con quienes te acompañan.",Virgo:"Virgo, tu mirada atenta nota lo que nadie más percibe; esta semana ordenar los detalles te dará tranquilidad y buenos resultados.",Libra:"Libra, tu sentido del equilibrio te hace buen mediador; esta semana te pide poner también tus propias necesidades en la balanza.",Escorpio:"Escorpio, tu intensidad te da profundidad y fuerza; esta semana te ayuda soltar lo que pesa para renovarte con calma.",Sagitario:"Sagitario, tu espíritu aventurero busca horizontes nuevos; esta semana una idea o un viaje pequeño puede cambiar tu perspectiva.",Capricornio:"Capricornio, tu disciplina sostiene tus metas; esta semana permite que el descanso y la alegría también ocupen un lugar en tu agenda.",Acuario:"Acuario, tu originalidad rompe moldes; esta semana una conversación con alguien distinto te regalará una idea que no esperabas.",Piscis:"Piscis, tu intuición y tu imaginación te guían con suavidad; esta semana confía en lo que sientes, pero apóyate en hechos concretos."};
const CIERRE=["Recuerda que las estrellas inclinan, pero tú decides: usa esta semana a tu favor y avanza con paso tranquilo.","Tómate un momento cada noche para agradecer lo vivido; esa pequeña pausa te mantendrá centrado hasta el domingo.","Si algo se complica a mitad de semana, respira y vuelve a lo esencial: el cierre llegará con más claridad.","Mantén la mente abierta y el corazón dispuesto: lo mejor de estos días llegará por donde menos lo esperas."];
